+      if (bl[0] === self) h = bl[1];
+      else if (bl[1] === self) h = bl[0];
+      else continue;
+      try { if (String(allAtomsTypeList3D[h - 1] || "").toUpperCase() !== "H") continue; } catch (eH) { continue; }
